    return bytearray(1024)

def read_input_to_buffer(buf):
    input_str = input()[:10]  # Read up to 10 characters
    num_chars = len(input_str)

    # Copy characters to buffer
    for i in range(num_chars):
        buf[i] = ord(input_str[i])

    # Ensure null terminator
    buf[num_chars] = 0

    return num_chars

