def allocate_buffer():
    # Alloue un tampon de 1024 octets
    return bytearray(1024)

def read_input(buf):
    # Lit 10 caractères depuis l'entrée standard et les stocke dans buf
    input_data = input()[:10]  # Limite à 10 caractères
    buf[:len(input_data)] = input_data.encode('utf-8')

def display_buffer(buf):
    # Affiche le contenu du tampon
    content = buf[:10].decode('utf-8', errors='ignore')
    print("Contenu du tampon :", content)

# Exemple d'utilisation
if __name__ == "__main__":
    buffer = allocate_buffer()
    read_input(buffer)
    display_buffer(buffer)

